            |> filter(fn: (r) => not exists r.isArchived or r.isArchived != "${IsArchived.archived}")`;

        const res = await queryApi.collectRows<InboxInfluxRow>(inboxFluxQuery);

        return res.map((row) => Inbox.dbModelToEntity(row));
    }
