    const s3client = new S3Client({
        region,
        credentials: {
            accessKeyId,
            secretAccessKey,
            sessionToken,
        },
    });
    const data = await s3client.send(new GetObjectCommand(params));
    return data;
};
export const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
